CREATE OR REPLACE FUNCTION private.validate_worker_areas_v1(areas jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare a jsonb; seen text[]:='{}'; key text;
begin
 if jsonb_typeof(areas) is distinct from 'array' or jsonb_array_length(areas)>5 then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
 for a in select value from jsonb_array_elements(areas) loop
  if jsonb_typeof(a)<>'object' or a-array['kind','countryCode','label','city','sourceRef','latitude','longitude','radiusKm']<>'{}'
   or not a?&array['kind','countryCode','label','city','sourceRef','latitude','longitude','radiusKm']
   or jsonb_typeof(a->'kind')<>'string' or a->>'kind' not in ('COUNTRY','CITY','RADIUS') or a->>'countryCode' is distinct from 'RS'
   or jsonb_typeof(a->'label')<>'string' or length(a->>'label') not between 2 and 200 or a->>'label'~'[[:cntrl:]]'
  then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
  if a->>'kind'='COUNTRY' then
   if jsonb_array_length(areas)<>1 or a->>'label'<>'Cela Srbija'
    or a->'city'<>'null' or a->'sourceRef'<>'null' or a->'latitude'<>'null' or a->'longitude'<>'null' or a->'radiusKm'<>'null'
   then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   key:='RS';
  else
   if jsonb_typeof(a->'city')<>'string' or length(a->>'city') not between 2 and 160 or a->>'city'~'[[:cntrl:]]'
    or jsonb_typeof(a->'sourceRef')<>'string' or a->>'sourceRef'!~'^osm:(node|way|relation):[1-9][0-9]{0,19}$'
    or jsonb_typeof(a->'latitude')<>'number' or jsonb_typeof(a->'longitude')<>'number'
   then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   if (a->>'latitude')::numeric not between -90 and 90 or (a->>'longitude')::numeric not between -180 and 180
    or round((a->>'latitude')::numeric,2)<>(a->>'latitude')::numeric or round((a->>'longitude')::numeric,2)<>(a->>'longitude')::numeric
   then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   if a->>'kind'='CITY' then
    if a->'radiusKm'<>'null' or a->>'label'<>a->>'city' then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   else
    if jsonb_typeof(a->'radiusKm')<>'number' or a->>'radiusKm'!~'^([1-9]|[1-9][0-9]|1[0-9][0-9]|200)$'
      or a->>'label'<>((a->>'city')||' · do '||(a->>'radiusKm')||' km') then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   end if;
   key:=a->>'sourceRef';
  end if;
  if key=any(seen) then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
  seen:=array_append(seen,key);
 end loop;
 return areas;
end $function$

CREATE OR REPLACE FUNCTION private.closure_taxonomy_project_v1(r text, t jsonb, a uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb;p jsonb:='{}';k text;semantic_key text;v jsonb;s jsonb;entry jsonb;rowvalue jsonb;projected jsonb;sections jsonb:='{}';owner text;
BEGIN
 SELECT x INTO c FROM jsonb_array_elements(private.closure_taxonomy_inventory_v1()) x WHERE x->>'relation'=r;
 IF c IS NULL THEN RAISE EXCEPTION 'F01_EXPORT_RELATION_INVALID';END IF;
 FOR k IN SELECT jsonb_array_elements_text(c->'fields') LOOP
  v:=t->k;
  IF k IN('proposals','plan','plans','result','binding_result','catalog_resolution') THEN v:=private.closure_taxonomy_semantic_v1(v);
  ELSIF k='portfolio' THEN v:=private.data_export_array_v5(v,'string');
  ELSIF k='payload' THEN
   FOR s IN SELECT jsonb_build_object('key',key,'fields',value) FROM jsonb_each(private.closure_taxonomy_reset_sections_v1()) LOOP
    entry:=v->(s->>'key');projected:='[]';
    FOR rowvalue IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(entry)='array' THEN entry WHEN jsonb_typeof(entry)='object' THEN jsonb_build_array(entry) ELSE '[]' END) LOOP
     owner:=coalesce(rowvalue->>'account_id',rowvalue->>'owner_account_id',rowvalue->>'worker_account_id');
     -- Snapshot arrays can contain foreign source copies; never trust only the outer owner.
     IF owner IS NOT NULL AND owner<>a::text THEN CONTINUE;END IF;
     SELECT coalesce(jsonb_object_agg(field,rowvalue->field),'{}') INTO entry FROM jsonb_array_elements_text(s->'fields') field;
     IF entry?'portfolio' THEN entry:=jsonb_set(entry,'{portfolio}',private.data_export_array_v5(entry->'portfolio','string'));END IF;
     IF entry?'candidate' THEN entry:=jsonb_set(entry,'{candidate}',private.data_export_worker_candidate_v5(entry->'candidate'));END IF;
     IF entry?'envelope' THEN entry:=jsonb_set(entry,'{envelope}',jsonb_build_object('profile',private.data_export_worker_candidate_v5(entry#>'{envelope,profile}')));END IF;
     FOR semantic_key IN SELECT unnest(ARRAY['proposals','plan','plans','result','binding_result','catalog_resolution']) LOOP
      IF entry?semantic_key THEN entry:=jsonb_set(entry,ARRAY[semantic_key],private.closure_taxonomy_semantic_v1(entry->semantic_key));END IF;
     END LOOP;
     projected:=projected||jsonb_build_array(entry);
    END LOOP;
    sections:=sections||jsonb_build_object(s->>'key',projected);
   END LOOP;
   v:=sections;
  END IF;
  p:=p||jsonb_build_object(k,v);
 END LOOP;
 RETURN p;
END $function$

CREATE OR REPLACE FUNCTION private.closure_taxonomy_scope_v1(r text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb;
BEGIN
 SELECT x INTO c FROM jsonb_array_elements(private.closure_taxonomy_inventory_v1()) x WHERE x->>'relation'=r;
 IF c IS NULL THEN RAISE EXCEPTION 'F01_RELATION_NOT_ADMITTED'; END IF;
 IF c->>'mode'='NEED' THEN
  RETURN format('t.%I in(select id from public.needs where requester_account_id=$1 union select s.id from private.dev_phase1_20261014_needs_snapshot s where s.requester_account_id=$1 and not exists(select 1 from public.needs n where n.id=s.id))',c->>'ownerColumn');
 END IF;
 RETURN format('t.%I=$1',c->>'ownerColumn');
END $function$
